explicit-before-logout.text:
application "winterm_XWsh-Desk 1" {
   command          "/emul/irix/usr/sbin/xwsh -name winterm -name winterm -title winterm -name winterm -geometry 80x24+10+180 -e /usr/libexec/xiri-shell "
   launchTime       "login"
   screen           "0"
}
application "winterm_XWsh-Desk 1+1" {
   command          "/emul/irix/usr/sbin/xwsh -name winterm -title winterm -geometry 80x24 -e /usr/libexec/xiri-shell "
   launchTime       "login"
   screen           "0"
}
application "xconsole_XConsole-Desk 1" {
   command          "xconsole -geometry 480x130-0-0 -daemon -notify -verbose -fn fixed -exitOnFail "
   launchTime       "login"
   screen           "0"
   iconx            "10"
   icony            "10"
}
application "xclock_XClock-Desk 1" {
   command          "/emul/irix/usr/bin/X11/xclock -display 127.0.0.1:0 -update 1 -geometry 180x180+820+20 -bg gray -fg black -bd black -hd black -hl black "
   launchTime       "login"
   screen           "0"
}
application "Windows_Windows-Desk 1" {
   launchTime       "login"
   screen           "0"
}
application "toolchest_Toolchest-Desk 1" {
   launchTime       "login"
   screen           "0"
}
4DWm*curNewBackground:	1
4DWm*Desk 1.backgroundDescription:	-bitmap /usr/include/X11/bitmaps/granite -bg #868686 -fg #69b5b5 
4Dwm*SG_autoSave:	False
